import { createContext, createEffect, useContext } from "solid-js";
import { createMutable, modifyMutable, produce } from "solid-js/store";

import { GameSetupParametersModel } from "#core/ui-next/screens/create-game/game-parameters-model.js";
import { ModelLifecycle, ModelRegistry } from "#core/ui-next/services/model-registry.js";

export interface AgeInfo {
	type: string;
	domain: string;
	name: string;
	description: string;
	icon: string;
	bgImage: string;
}

export interface MutableAgeModel {
	sortedAges: AgeInfo[];
	selectedAge: AgeInfo;
	nextAge: AgeInfo;
	getAgeName: (ageType: string) => string | undefined;
	setSelectedAge: (age: AgeInfo) => void;
	getAgeIcon: (ageType: string) => string | undefined;
}

export interface AgeModel extends MutableAgeModel {
	readonly sortedAges: AgeInfo[];
	readonly selectedAge: AgeInfo;
	readonly getAgeName: (ageType: string) => string | undefined;
	readonly setSelectedAge: (age: AgeInfo) => void;
	readonly getAgeIcon: (ageType: string) => string | undefined;
}

export function createAgeSelectModel(): AgeModel {
	const ageParameter = GameSetupParametersModel.get().Age;
	const ageNames = new Map<string, string>();

	const getAgeData = () => {
		const sortedAges: AgeInfo[] = [];
		const agesDomainValues = [...(ageParameter.domain.possibleValues ?? [])];
		const sortedValues = agesDomainValues.sort((a, b) => a.sortIndex - b.sortIndex);

		for (const age of sortedValues) {
			// TODO: this should be data driven somehow
			const type = age.value as string;

			const ageInfo: AgeInfo = {
				type,
				name: GameSetup.resolveString(age.name) || "",
				description: GameSetup.resolveString(age.description) || "",
				icon: `url(${UI.getIcon(type) || ""})`,
				bgImage: UI.getIconBLP(type, "BACKGROUND_HORIZ"),
				domain: GameSetup.resolveString(age.originDomain) || "",
			};

			sortedAges.push(ageInfo);
			ageNames.set(ageInfo.type, ageInfo.name);
		}

		const currentAge = ageParameter.value.value as string | undefined;
		const selectedAgeIndex = sortedAges.findIndex((age) => age.type == currentAge);

		const selectedAge = sortedAges[selectedAgeIndex >= 0 ? selectedAgeIndex : 0];
		const nextAge = selectedAgeIndex + 1 < sortedAges.length ? sortedAges[selectedAgeIndex + 1] : selectedAge;

		// During age transition we want to show the next age info
		const isAgeTransition = UI.isInGame();

		return { sortedAges, selectedAge: isAgeTransition ? nextAge : selectedAge, nextAge };
	};

	const ageData = {
		...getAgeData(),
		getAgeName: (ageType: string) => ageNames.get(ageType),
		setSelectedAge: (age: AgeInfo) => ageParameter.setValue(age.type),
		getAgeIcon: (ageType: string) => `url(${UI.getIcon(ageType) || ""})`,
	};

	const ageMutable: MutableAgeModel = createMutable(ageData);

	createEffect(() => {
		const ageData = getAgeData();
		modifyMutable(
			ageMutable,
			produce((ageModel) => {
				ageModel.sortedAges = ageData.sortedAges;
				ageModel.selectedAge = ageData.selectedAge;
			}),
		);
	});

	return ageMutable;
}

export const AgeSelectModel = ModelRegistry.register(
	"AgeSelectModel",
	ModelLifecycle.SharedInstance,
	createAgeSelectModel,
);

export const AgeSelectModelContext = createContext<AgeModel>();

export function useAgeSelectModelContext() {
	const context = useContext(AgeSelectModelContext);

	if (!context) {
		throw new Error("useAgeSelectModelContext: Cannot find context!");
	}

	return context;
}
